def prime_fib(n: int):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def fibonacci():
        a, b = 0, 1
        while True:
            a, b = b, a + b
            yield a

    fib_gen = fibonacci()
    prime_fib_numbers = []

    while len(prime_fib_numbers) < n:
        fib_number = next(fib_gen)
        if is_prime(fib_number):
            prime_fib_numbers.append(fib_number)

    return prime_fib_numbers[-1]

